using BARANG.Core.Domain.Common;

namespace BARANG.Core.Domain.Production;
public enum ProductionJobType{DesignPreparation,Print,HeatPress}
public enum ProductionJobStatus{Planned,Ready,InProgress,Suspended,Completed,Failed}
public enum ProductionPriority{Low,Normal,High,Urgent}
public static class ProductionErrors{public static Error Invalid=>Error.Validation("production.invalid_data");public static Error NotFound=>Error.NotFound("production.job.not_found");public static Error InvalidTransition=>Error.BusinessRule("production.invalid_transition");public static Error ReasonRequired=>Error.Validation("production.reason_required");public static Error AssignmentRequired=>Error.BusinessRule("production.assignment_required");public static Error IncompatibleEquipment=>Error.BusinessRule("production.incompatible_equipment");public static Error InvalidOperator=>Error.BusinessRule("production.invalid_operator");public static Error OrderNotEligible=>Error.BusinessRule("production.order_not_eligible");public static Error Concurrency=>Error.Concurrency("production.concurrency_conflict");}
public static class ProductionText{public static string? Text(string?x,int max,bool optional=false){if(string.IsNullOrWhiteSpace(x))return optional?null:null;string s=x.Trim();return s.Length<=max?s:null;}public static string Key(Guid item,ProductionJobType type,Guid?operation)=>$"{item:N}:{type}:{operation?.ToString("N")??"NONE"}";}
public sealed class ProductionJob
{
 private ProductionJob(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OrderId{get;private set;}public Guid OrderItemId{get;private set;}public Guid? PrintOperationId{get;private set;}public ProductionJobType JobType{get;private set;}public ProductionJobStatus Status{get;private set;}public ProductionPriority Priority{get;private set;}public int QueuePosition{get;private set;}public Guid? AssignedOperatorUserId{get;private set;}public Guid? AssignedEquipmentId{get;private set;}public DateTimeOffset? PlannedStartUtc{get;private set;}public DateTimeOffset? PlannedEndUtc{get;private set;}public DateTimeOffset? StartedAtUtc{get;private set;}public DateTimeOffset? CompletedAtUtc{get;private set;}public string? FailureReason{get;private set;}public string? SuspensionReason{get;private set;}public Guid? ArtworkVersionId{get;private set;}public Guid? FileVersionId{get;private set;}public decimal? QuantityCompleted{get;private set;}public string? ExecutionNotes{get;private set;}public string GenerationKey{get;private set;}="";public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}
 public static Result<ProductionJob>Create(Guid company,Guid order,Guid item,Guid?operation,ProductionJobType type,Guid?artwork,Guid?file,DateTimeOffset now){if(company==Guid.Empty||order==Guid.Empty||item==Guid.Empty||!Enum.IsDefined(type)||(type==ProductionJobType.Print&&operation is null)||(type!=ProductionJobType.Print&&operation is not null))return Result.Failure<ProductionJob>(ProductionErrors.Invalid);return Result.Success(new ProductionJob{Id=Guid.NewGuid(),CompanyId=company,OrderId=order,OrderItemId=item,PrintOperationId=operation,JobType=type,Status=ProductionJobStatus.Planned,Priority=ProductionPriority.Normal,GenerationKey=ProductionText.Key(item,type,operation),ArtworkVersionId=artwork,FileVersionId=file,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}
 public Result Plan(ProductionPriority priority,DateTimeOffset?start,DateTimeOffset?end,int queue,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);if(Status is ProductionJobStatus.Completed or ProductionJobStatus.Failed||end<=start||queue<0)return Result.Failure(ProductionErrors.Invalid);Priority=priority;PlannedStartUtc=start;PlannedEndUtc=end;QueuePosition=queue;Status=ProductionJobStatus.Ready;Touch(now);return Result.Success();}
 public Result AssignOperator(Guid user,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);if(Status is ProductionJobStatus.Completed or ProductionJobStatus.Failed||user==Guid.Empty)return Result.Failure(ProductionErrors.InvalidTransition);AssignedOperatorUserId=user;Touch(now);return Result.Success();}
 public Result AssignEquipment(Guid?equipment,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);if(Status is ProductionJobStatus.Completed or ProductionJobStatus.Failed)return Result.Failure(ProductionErrors.InvalidTransition);AssignedEquipmentId=equipment;Touch(now);return Result.Success();}
 public Result Start(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);if(Status!=ProductionJobStatus.Ready||AssignedOperatorUserId is null||(JobType!=ProductionJobType.DesignPreparation&&AssignedEquipmentId is null))return Result.Failure(ProductionErrors.AssignmentRequired);Status=ProductionJobStatus.InProgress;StartedAtUtc??=now;SuspensionReason=null;Touch(now);return Result.Success();}
 public Result Complete(decimal?quantity,string?notes,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);string?n=ProductionText.Text(notes,1000,true);if(Status!=ProductionJobStatus.InProgress||quantity<0||(!string.IsNullOrWhiteSpace(notes)&&n is null))return Result.Failure(ProductionErrors.InvalidTransition);Status=ProductionJobStatus.Completed;CompletedAtUtc=now;QuantityCompleted=quantity;ExecutionNotes=n;Touch(now);return Result.Success();}
 public Result Fail(string reason,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);string?r=ProductionText.Text(reason,500);if(r is null)return Result.Failure(ProductionErrors.ReasonRequired);if(Status is not(ProductionJobStatus.Ready or ProductionJobStatus.InProgress or ProductionJobStatus.Suspended))return Result.Failure(ProductionErrors.InvalidTransition);Status=ProductionJobStatus.Failed;FailureReason=r;CompletedAtUtc=now;Touch(now);return Result.Success();}
 public Result Suspend(string reason,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);string?r=ProductionText.Text(reason,500);if(r is null)return Result.Failure(ProductionErrors.ReasonRequired);if(Status!=ProductionJobStatus.InProgress)return Result.Failure(ProductionErrors.InvalidTransition);Status=ProductionJobStatus.Suspended;SuspensionReason=r;Touch(now);return Result.Success();}
 public Result Resume(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(ProductionErrors.Concurrency);if(Status!=ProductionJobStatus.Suspended)return Result.Failure(ProductionErrors.InvalidTransition);Status=ProductionJobStatus.InProgress;SuspensionReason=null;Touch(now);return Result.Success();}private void Touch(DateTimeOffset now){UpdatedAtUtc=now;Version++;}
}
public sealed class ProductionJobHistory{private ProductionJobHistory(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid ProductionJobId{get;private set;}public string EventType{get;private set;}="";public Guid ActorUserId{get;private set;}public DateTimeOffset OccurredAtUtc{get;private set;}public string? Summary{get;private set;}public static ProductionJobHistory Create(Guid company,Guid job,string type,Guid actor,DateTimeOffset now,string?summary=null)=>new(){Id=Guid.NewGuid(),CompanyId=company,ProductionJobId=job,EventType=type,ActorUserId=actor,OccurredAtUtc=now,Summary=ProductionText.Text(summary,500,true)};}
